443		if err := e.Modify(id, 4, 10); err != nil {
444			t.Fatalf("缺口时重复提交当前参数应成功: %v", err)
445		}
446		if len(e.Records()) != recs+1 {
447			t.Fatal("重复提交不得新增记录")
448		}
449		// 降价但提量：剩余量增加，拒绝（不能借降价绕开）。
450		if err := e.Modify(id, 5, 1); err == nil {
451			t.Fatal("缺口时不得靠降价增加剩余量")
452		}
453		// 量价都不增：4@8 → 现金 32、金额 4×max(8,10)=40，均不增，允许。
454		mustModify(t, e, id, 4, 8)
455		if e.ReservedCash() != 32 {
456			t.Fatalf("量价不增的修改应允许: reserved=%d", e.ReservedCash())
457		}
