459		// 报价高于限价时，金额口径按报价计：提量会同时抬高金额占用，仍被剩余量规则拦截。
460		// 这里直接验证等待中的 seq3@99 从未参与（补齐前占用不随其变化）。
461		if o, _ := e.Order(id); o.Qty != 4 || o.Limit != 8 {
462			t.Fatalf("订单参数错误: %+v", o)
463		}
464	
465		// 补齐 seq2、seq3 后，剩余部分按新限价与新剩余量成交（@8 四股）。
466		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 10}, 2)
467		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 8, Qty: 4}); err != nil {
468			t.Fatalf("补齐后应按新参数成交: %v", err)
469		}
470		if e.Position("A") != 4 || e.ReservedCash() != 0 {
471			t.Fatalf("按新参数成交后账目错误: pos=%d reserved=%d", e.Position("A"), e.ReservedCash())
472		}
473	
474		// 缺口期间卖单修改仍可办理（另有持仓）。
475		e2 := setupModify(t)
476		bid := mustBuy(t, e2, "A", 10, 10)
477		if _, err := e2.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
478			t.Fatal(err)
479		}
480		sid := mustSell(t, e2, "A", 5, 9)
481		mustQuote(t, e2, "A", Quote{Seq: 3, Moment: 3, Price: 10}, 0)
482		mustModify(t, e2, sid, 8, 9) // 缺口不阻止卖单修改
483		if e2.Sellable("A") != 2 {
484			t.Fatalf("缺口时卖单修改应正常调整占用: %d", e2.Sellable("A"))
